using System;using System.Runtime.InteropServices;using System.Windows.Automation;
public static class OwnedCapabilityTableInput {
 [StructLayout(LayoutKind.Sequential)]public struct POINT{public int x,y;}
 [StructLayout(LayoutKind.Sequential)]public struct MOUSE{public int x,y;public uint data,flags,time;public UIntPtr extra;}
 [StructLayout(LayoutKind.Sequential)]public struct KEY{public ushort vk,scan;public uint flags,time;public UIntPtr extra;}
 [StructLayout(LayoutKind.Explicit,Size=32)]public struct UNION{[FieldOffset(0)]public MOUSE mouse;[FieldOffset(0)]public KEY key;}
 [StructLayout(LayoutKind.Sequential)]public struct INPUT{public uint type;public UNION data;}
 [DllImport("user32.dll",SetLastError=true)]static extern uint SendInput(uint n,INPUT[] events,int size);
 [DllImport("user32.dll")]static extern int GetSystemMetrics(int n);
 [DllImport("user32.dll")]static extern bool GetCursorPos(out POINT p);
 [DllImport("user32.dll")]static extern bool GetPhysicalCursorPos(out POINT p);
 [DllImport("user32.dll")]static extern IntPtr SetThreadDpiAwarenessContext(IntPtr c);
 [DllImport("user32.dll")]static extern IntPtr GetThreadDpiAwarenessContext();
 [DllImport("user32.dll")]static extern int GetAwarenessFromDpiAwarenessContext(IntPtr c);
 [DllImport("user32.dll")]static extern IntPtr GetForegroundWindow();
 [DllImport("user32.dll")]static extern bool SetForegroundWindow(IntPtr w);
 static void Emit(INPUT i){if(SendInput(1,new[]{i},Marshal.SizeOf<INPUT>())!=1)throw new InvalidOperationException("SendInput failed");}
 static void KeyEvent(ushort vk,bool down){Emit(new INPUT{type=1,data=new UNION{key=new KEY{vk=vk,flags=down?0u:2u}}});}
 static void Mouse(uint flags,uint data){Emit(new INPUT{type=0,data=new UNION{mouse=new MOUSE{flags=flags,data=data}}});}
 static void Move(int x,int y){int l=GetSystemMetrics(76),t=GetSystemMetrics(77),w=GetSystemMetrics(78),h=GetSystemMetrics(79);if(w<=1||h<=1||x<l||x>=l+w||y<t||y>=t+h)throw new InvalidOperationException("Display bounds failed");Emit(new INPUT{type=0,data=new UNION{mouse=new MOUSE{x=(int)Math.Round((x-l)*65535d/(w-1)),y=(int)Math.Round((y-t)*65535d/(h-1)),flags=0xC001}}});}

 public static string Run(bool source,string app,string mode){
  if(mode!="pointer"&&mode!="key"&&mode!="passive")throw new InvalidOperationException("Fixed Table input mode required");
  if(!System.Text.RegularExpressions.Regex.IsMatch(app,@"\\DBMV-Isolated-preflight-capabilitytable-[0-9a-f]{32}\\app$"))throw new InvalidOperationException("Owned cold Table path required");
  string transport=System.IO.Path.Combine(app,"capabilitytable-pointer-transport.txt");POINT logicalBefore,physicalBefore;GetCursorPos(out logicalBefore);GetPhysicalCursorPos(out physicalBefore);System.IO.File.WriteAllText(transport,"beforeAwareness="+GetAwarenessFromDpiAwarenessContext(GetThreadDpiAwarenessContext())+" beforeScreen="+GetSystemMetrics(78)+"x"+GetSystemMetrics(79)+" logicalCursor="+logicalBefore.x+","+logicalBefore.y+" physicalCursor="+physicalBefore.x+","+physicalBefore.y+"\n");var oldDpi=SetThreadDpiAwarenessContext(new IntPtr(-4));try{System.IO.File.AppendAllText(transport,"afterAwareness="+GetAwarenessFromDpiAwarenessContext(GetThreadDpiAwarenessContext())+" afterScreen="+GetSystemMetrics(78)+"x"+GetSystemMetrics(79)+"\n");
  AutomationElement window=null;foreach(AutomationElement w in AutomationElement.RootElement.FindAll(TreeScope.Children,Condition.TrueCondition)){var process=System.Diagnostics.Process.GetProcessById(w.Current.ProcessId);bool match=source?w.Current.Name.StartsWith("CapabilityTable Input · original isolation",StringComparison.Ordinal)&&process.MainModule.FileName.EndsWith(@"\Microsoft\Edge\Application\msedge.exe",StringComparison.OrdinalIgnoreCase):w.Current.Name=="Replica CapabilityTable verification"&&process.MainModule.FileName.Equals(System.IO.Path.Combine(app,"ReplicaProbe.exe"),StringComparison.OrdinalIgnoreCase);if(!match)continue;if(window!=null)throw new InvalidOperationException("Owned Table window not unique");window=w;}if(window==null)throw new InvalidOperationException("Owned Table missing");
  Func<string,AutomationElement> find=id=>window.FindFirst(TreeScope.Descendants,new PropertyCondition(AutomationElement.AutomationIdProperty,id));var button=find("CapabilityRow-permissions");var table=find(source?"CapabilityTable-source":"CapabilityTable-root");if(button==null||table==null||button.Current.ControlType!=ControlType.Button||!button.Current.IsEnabled)throw new InvalidOperationException("Exact Table named control absent");if(button.Current.Name!="필요한 권한 보기"&&button.Current.Name!="Required permissions")throw new InvalidOperationException("Unexpected permission label");
  var frame=window.Current.BoundingRectangle;var b=button.Current.BoundingRectangle;const double scale=2;if(b.Height/scale<44||b.Height/scale>45||b.Width/scale<80||b.Width/scale>250)throw new InvalidOperationException("Source/native permission geometry guard failed");SetForegroundWindow(new IntPtr(window.Current.NativeWindowHandle));if(mode=="key")button.SetFocus();System.Threading.Thread.Sleep(100);
  Action guard=()=>{if(GetForegroundWindow().ToInt64()!=window.Current.NativeWindowHandle)throw new InvalidOperationException("Owned Table foreground/focus lost");};guard();POINT old;if(!GetPhysicalCursorPos(out old))throw new InvalidOperationException("Cursor read failed");bool mouseDown=false,keyDown=false;var before=DateTime.UtcNow;
  try{
   if(mode=="key"){var focused=AutomationElement.FocusedElement;if(focused.Current.AutomationId!="CapabilityRow-permissions")throw new InvalidOperationException("Fresh exact permission focus absent");KeyEvent(13,true);keyDown=true;System.Threading.Thread.Sleep(25);guard();KeyEvent(13,false);keyDown=false;}
   else{var t=table.Current.BoundingRectangle;if(mode=="passive"&&(t.Width/scale<900||t.Width/scale>907||t.Height/scale<315||t.Height/scale>350))throw new InvalidOperationException("Wide parent passive geometry required");int x=(int)Math.Round(mode=="pointer"?b.Left+b.Width/2:t.Left+60*scale),y=(int)Math.Round(mode=="pointer"?b.Top+b.Height/2:t.Top+70*scale);if(!frame.Contains(new System.Windows.Point(x,y)))throw new InvalidOperationException("Table point outside window");Move(x,y);System.Threading.Thread.Sleep(60);guard();POINT actual;if(!GetPhysicalCursorPos(out actual))throw new InvalidOperationException("Physical cursor unavailable");System.IO.File.AppendAllText(transport,"requested="+x+","+y+" actual="+actual.x+","+actual.y+" table="+t+"\n");if(Math.Abs(actual.x-x)>1||Math.Abs(actual.y-y)>1)throw new InvalidOperationException("Physical point mismatch before click");var hit=AutomationElement.FromPoint(new System.Windows.Point(actual.x,actual.y));if(hit==null||hit.Current.ProcessId!=window.Current.ProcessId)throw new InvalidOperationException("Table pointer hit different process");for(var e=hit; e!=null&&e.Current.ProcessId==window.Current.ProcessId; e=TreeWalker.ControlViewWalker.GetParent(e)){System.IO.File.AppendAllText(transport,"hit="+e.Current.ControlType.ProgrammaticName+" id="+e.Current.AutomationId+" box="+e.Current.BoundingRectangle+"\n");if(e==window)break;}
   Mouse(2,0);mouseDown=true;System.Threading.Thread.Sleep(35);guard();Mouse(4,0);mouseDown=false;}
   System.Threading.Thread.Sleep(650);guard();var afterFocus=AutomationElement.FocusedElement;System.IO.File.AppendAllText(transport,"postFocus="+(afterFocus==null?"none":afterFocus.Current.AutomationId)+"\n");if(source)return "Fresh original Table "+mode+" completed with passive recorder";var file=System.IO.Path.Combine(app,"capabilitytable-input.json");if(System.IO.File.GetLastWriteTimeUtc(file)<=before)throw new InvalidOperationException("Native Table fresh record absent");using(var stream=new System.IO.FileStream(file,System.IO.FileMode.Open,System.IO.FileAccess.Read,System.IO.FileShare.ReadWrite|System.IO.FileShare.Delete))using(var reader=new System.IO.StreamReader(stream))return reader.ReadToEnd();
  }finally{if(keyDown)KeyEvent(13,false);if(mouseDown)Mouse(4,0);if(GetForegroundWindow().ToInt64()==window.Current.NativeWindowHandle)Move(old.x,old.y);}
  }finally{if(oldDpi!=IntPtr.Zero)SetThreadDpiAwarenessContext(oldDpi);}
 }
}
